{
  "root_causes": [
    {
      "service": "ts-admin-basic-info-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50ms, round(quantile_cont(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name LIKE '%getAllContacts%' GROUP BY ALL",
          "claim": "getAllContacts internal method self-time rose to about 1718 ms p50 over 27 calls, versus about 8 ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'norm' src, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms FROM normal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name LIKE '%getAllContacts%' GROUP BY ALL",
          "claim": "In the normal period getAllContacts p95 was about 8.9 ms across 43 calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name LIKE 'GET /api/v1/adminbasicservice/adminbasic/%' GROUP BY ALL ORDER BY 2",
          "claim": "Only the /contacts GET server endpoint is slow (1721 ms p95); configs, prices, stations, trains stay at 5-9 ms, with no errors."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-admin-basic-info-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%adminbasicservice/adminbasic/contacts%' GROUP BY ALL",
          "claim": "ts-ui-dashboard's GET adminbasic/contacts server span shows the same ~1720 ms p95 as the callee, while its other admin endpoints stay fast."
        }
      ]
    }
  ]
}
```

